@using sv_917564e9ddb64e5e8ab79ec6d42e8da6.Services

<div class="change-password-panel">
    <button class="panel-toggle" @onclick="() => _expanded = !_expanded">
        <span>Change Password</span>
        <span class="toggle-indicator">@(_expanded ? "▲" : "▼")</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="toast error">@_error</div>
            }

            @if (_showSuccess)
            {
                <div class="toast success">Password updated successfully!</div>
            }

            <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _error;
    private bool _showSuccess;

    private async Task UpdatePassword()
    {
        _error = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
    }
}

@using sv_917564e9ddb64e5e8ab79ec6d42e8da6.Services

<div class="active-sessions-table">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table>
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn-danger btn-small" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-session-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="confirmation-dialog-overlay">
            <div class="confirmation-dialog">
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> (@_sessionToRevoke.Location)?</p>
                <div class="dialog-actions">
                    <button class="btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }
}

