@using sv_917564e9ddb64e5e8ab79ec6d42e8da6.Services

<div class="security-section">
    <h2>Security Settings</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel SettingsService="SettingsService" />

        <div class="two-factor-section">
            <h3>Two-Factor Authentication</h3>
            <div class="two-factor-toggle">
                <label class="toggle-item">
                    <input type="checkbox" checked="@_twoFactorEnabled" disabled />
                    <span>Two-Factor Authentication</span>
                </label>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("f")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnRevoke="RevokeSession" />
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // Assume the first session is the current one
        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
        _loading = false;
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
    }
}

@using sv_917564e9ddb64e5e8ab79ec6d42e8da6.Services

<div class="appearance-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="setting-group">
            <h3>Theme</h3>
            <div class="radio-group">
                <label>
                    <input type="radio" name="theme" value="Light"
                           checked="@(_theme == "Light")"
                           @onchange="() => _theme = \"Light\"" />
                    Light
                </label>
                <label>
                    <input type="radio" name="theme" value="Dark"
                           checked="@(_theme == "Dark")"
                           @onchange="() => _theme = \"Dark\"" />
                    Dark
                </label>
                <label>
                    <input type="radio" name="theme" value="System"
                           checked="@(_theme == "System")"
                           @onchange="() => _theme = \"System\"" />
                    System
                </label>
            </div>
        </div>

        <div class="setting-group">
            <h3>Font Size</h3>
            <div class="radio-group">
                <label>
                    <input type="radio" name="fontSize" value="Small"
                           checked="@(_fontSize == "Small")"
                           @onchange="() => _fontSize = \"Small\"" />
                    Small
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Medium"
                           checked="@(_fontSize == "Medium")"
                           @onchange="() => _fontSize = \"Medium\"" />
                    Medium
                </label>
                <label>
                    <input type="radio" name="fontSize" value="Large"
                           checked="@(_fontSize == "Large")"
                           @onchange="() => _fontSize = \"Large\"" />
                    Large
                </label>
            </div>
        </div>

        <div class="setting-group">
            <h3>Language</h3>
            <select @bind="_language">
                <option value="en">English</option>
                <option value="es">Español</option>
                <option value="fr">Français</option>
                <option value="de">Deutsch</option>
                <option value="ja">日本語</option>
                <option value="zh">中文</option>
            </select>
        </div>

        <div class="setting-group">
            <h3>Compact Mode</h3>
            <label class="toggle-item">
                <input type="checkbox" @bind="_compactMode" />
                <span>Enable compact mode</span>
            </label>
        </div>

        <div class="live-preview" style="@GetPreviewStyle()">
            <h4>Live Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p>The quick brown fox jumps over the lazy dog.</p>
        </div>

        <div class="form-actions">
            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
        </div>

        @if (_showSuccess)
        {
            <div class="toast success">Appearance settings saved!</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _showSuccess;
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1e1e1e; color: #ffffff;",
            "Light" => "background-color: #ffffff; color: #000000;",
            _ => "background-color: #f5f5f5; color: #333333;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size: 12px;",
            "Large" => "font-size: 18px;",
            _ => "font-size: 14px;"
        };

        var padding = _compactMode ? "padding: 8px;" : "padding: 16px;";

        return $"{bg} {font} {padding} border-radius: 8px; border: 1px solid #ddd; margin-top: 16px;";
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

