+
+.dialog-actions {
+    margin-top: 1rem;
+    display: flex;
+    gap: 0.75rem;
+    justify-content: flex-end;
+}
+
+/* Appearance section */
+.setting-group {
+    margin-bottom: 1.25rem;
+}
+
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
